    var wallQueue=new Fixture();var w1=wallQueue.start("one");var w2=wallQueue.start("two");check(wallQueue.owner.admitPublication(wallQueue.source,"expires-in-queue",1,"",List.of(List.of("expiration",Long.toString(wallQueue.time.wall+1))),0)!=null);wallQueue.time.wall++;wallQueue.owner.drained(w1);check(wallQueue.owner.startNext()==null&&wallQueue.owner.waiting()==0);wallQueue.owner.drained(w2);
