    Time time=new Time();var owner=new NativeMeshAuthority(()->time.now,()->time.wall);owner.foreground(true);owner.account(USER,1,"vault",1,true,1);var req=owner.admitPairing(PUB,OTHER,VERSION,bytes(1,16),bytes(1,32),bytes(161,32),bytes(193,32),time.wall+1,true);check(req!=null&&owner.approvePairing(req));var permit=owner.startNext();check(owner.begin(permit));time.wall++;check(owner.signPairing(permit,c->{throw new AssertionError();})==null&&owner.running()==1);owner.drained(permit);
